use vstd::prelude::*;

verus! {
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        requires
            a.len() <= 0x1_0000_0000, // Assuming the length of the vector fits within a reasonable limit
        ensures
            result.len() == a.len(),
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[i],
    {
        let mut result: Vec<T> = Vec::new();
        let mut idx: nat = 0;

        while idx < a.len()
            invariant
                idx <= a.len(),
                result.len() == idx,
                forall|j: nat| 0 <= j < idx ==> result[j] == a[j],
            decreases a.len() - idx,
        {
            result.push(a[idx]);
            idx = idx + 1;
        }

        result
    }
}
